    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        List<String> tokens = new ArrayList<>();
        while (st.hasMoreTokens()) tokens.add(st.nextToken());
        TreeNode root = new TreeNode(Long.parseLong(tokens.get(0)));
        ArrayDeque<TreeNode> q = new ArrayDeque<>();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < tokens.size()) {
            TreeNode node = q.poll();
            if (i < tokens.size() && !tokens.get(i).equals("null")) {
                node.left = new TreeNode(Long.parseLong(tokens.get(i)));
                q.add(node.left);
            }
            i++;
            if (i < tokens.size() && !tokens.get(i).equals("null")) {
                node.right = new TreeNode(Long.parseLong(tokens.get(i)));
                q.add(node.right);
            }
            i++;
        }
        List<Long> res = leftThenRightView(root);
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < res.size(); k++) sb.append(res.get(k)).append(k + 1 < res.size() ? " " : "\n");
        System.out.print(sb);
    }
}
